   643	/// Poll `wg show <iface> latest-handshakes` and re-write the sled + xray config
   644	/// whenever a new peer handshake is detected.  Runs forever; call from a thread.
   645	pub fn watch_wireguard_handshakes(iface: &str) {
   646	    let iface = iface.to_string();
   647	    let poll_secs = std::time::Duration::from_secs(15);
   648	    let mut seen: HashSet<String> = HashSet::new();
   649	
   650	    loop {
   651	        std::thread::sleep(poll_secs);
   652	
   653	        // wg0 lives inside the wg-xray Incus container, not on the host.
   654	        let Ok(out) = Command::new("incus")
   655	            .args([
   656	                "exec",
   657	                "wg-xray",
   658	                "--",
   659	                "wg",
   660	                "show",
   661	                &iface,
   662	                "latest-handshakes",
   663	            ])
   664	            .output()
   665	        else {
   666	            continue;
   667	        };
   668	
   669	        if !out.status.success() {
   670	            continue;
   671	        }
   672	
   673	        let stdout = String::from_utf8_lossy(&out.stdout);
   674	        for line in stdout.lines() {
   675	            let mut parts = line.split('\t');
   676	            let (Some(pubkey), Some(ts_str)) = (parts.next(), parts.next()) else {
   677	                continue;
   678	            };
   679	            let ts: u64 = ts_str.trim().parse().unwrap_or(0);
   680	            if ts == 0 {
   681	                continue;
   682	            }
   683	
   684	            // Treat any handshake within the last 3 minutes as "new" if not yet seen
   685	            let now = std::time::SystemTime::now()
   686	                .duration_since(std::time::UNIX_EPOCH)
   687	                .map(|d| d.as_secs())
   688	                .unwrap_or(0);
   689	            if now.saturating_sub(ts) > 180 {
   690	                continue;
   691	            }
   692	
   693	            let key = format!("{}:{}", pubkey, ts);
   694	            if seen.contains(&key) {
   695	                continue;
   696	            }
   697	            seen.insert(key);
   698	
   699	            tracing::info!(peer = %pubkey, "WireGuard handshake → updating identity sled");
   700	
   701	            if let Err(e) = write_sled_from_wg(pubkey) {
   702	                tracing::warn!("write_sled_from_wg failed: {}", e);
   703	                continue;
   704	            }
