    36	    pub next_of_id: Arc<Mutex<u64>>,
    37	}
    38	
    39	impl DaemonState {
    40	    pub fn new(socket_path: String) -> Self {
    41	        Self {
    42	            ovsdb: Arc::new(Mutex::new(None)),
    43	            socket_path,
    44	            of_conns: Arc::new(Mutex::new(HashMap::new())),
    45	            next_of_id: Arc::new(Mutex::new(1)),
